def transform(grid):
    if not grid:
        return grid

    rows = len(grid)
    if rows == 0:
        return grid
    cols = len(grid[0])

    # Find background color (most frequent)
    from collections import Counter
    all_values = [cell for row in grid for cell in row]
    background = Counter(all_values).most_common(1)[0][0]

    # Copy input to output
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # For each row, find non-background cells and apply the pattern
    for r in range(rows):
        # Find all non-background positions
        non_bg = [(c, grid[r][c]) for c in range(cols) if grid[r][c] != background]

        for c, val in non_bg:
            # Apply alternating pattern starting from column c
            for i in range(c, cols):
                if (i - c) % 2 == 0:
                    output[r][i] = val
                else:
                    output[r][i] = 5

    return output
